{"command":"cat <<'EOF' > main.go
package main

import (
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"io"
	"math"
	"net/http"
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

var defaultMap = " .:-=+*#%@"
var complexMap = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"

type Config struct {
	Color       bool
	ColorBG     bool
	Dimensions  [2]int
	Width       int
	Height      int
	Map         string
	Braille     bool
	Threshold   int
	Dither      bool
	Grayscale   bool
	Complex     bool
	Full        bool
	Negative    bool
	FlipX       bool
	FlipY       bool
	SaveImg     string
	SaveTxt     string
	SaveGif     string
	Font        string
	FontColor   [3]int
	SaveBG      [4]int
	OnlySave    bool
}

func decodeBMP(r io.Reader) (image.Image, error) {
	var header [14]byte
	if _, err := io.ReadFull(r, header[:]); err != nil {
		return nil, err
	}
	if header[0] != 'B' || header[1] != 'M' {
		return nil, fmt.Errorf("not a BMP")
	}
	var dibHeader [40]byte
	if _, err := io.ReadFull(r, dibHeader[:]); err != nil {
		return nil, err
	}
	width := int(int32(binary.LittleEndian.Uint32(dibHeader[4:8])))
	height := int(int32(binary.LittleEndian.Uint32(dibHeader[8:12])))
	bitCount := binary.LittleEndian.Uint16(dibHeader[14:16])
	if bitCount != 24 {
		return nil, fmt.Errorf("only 24-bit BMP supported")
	}
	absHeight := int(math.Abs(float64(height)))
	img := image.NewRGBA(image.Rect(0, 0, width, absHeight))
	rowSize := (width*3 + 3) &^ 3
	rowData := make([]byte, rowSize)
	for y := 0; y < absHeight; y++ {
		if _, err := io.ReadFull(r, rowData); err != nil {
			return nil, err
		}
		actualY := y
		if height > 0 {
			actualY = absHeight - 1 - y
		}
		for x := 0; x < width; x++ {
			b := rowData[x*3]
			g := rowData[x*3+1]
			r := rowData[x*3+2]
			img.Set(x, actualY, color.RGBA{r, g, b, 255})
		}
	}
	return img, nil
}

func init() {
	image.RegisterFormat("bmp", "BM", decodeBMP, func(r io.Reader) (image.Config, error) {
		var h [26]byte
		if _, err := io.ReadFull(r, h[:]); err != nil {
			return image.Config{}, err
		}
		return image.Config{
			ColorModel: color.RGBAModel,
			Width:      int(binary.LittleEndian.Uint32(h[18:22])),
			Height:     int(binary.LittleEndian.Uint32(h[22:26])),
		}, nil
	})
}

func getTerminalSize() (int, int) {
	width, height := 80, 24
	fd := int(os.Stdout.Fd())
	var dimensions [4]uint16
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&dimensions)), 0, 0, 0)
	if err == 0 {
		width = int(dimensions[1])
		height = int(dimensions[0])
	}
	return width, height
}

func main() {
	config := Config{
		Threshold: 128,
		FontColor: [3]int{255, 255, 255},
		SaveBG:    [4]int{0, 0, 0, 100},
	}
	var inputs []string
	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		switch arg {
		case "-C", "--color":
			config.Color = true
		case "--color-bg":
			config.ColorBG = true
		case "-d", "--dimensions":
			i++
			if i < len(os.Args) {
				parts := strings.Split(os.Args[i], ",")
				if len(parts) == 2 {
					config.Dimensions[0], _ = strconv.Atoi(parts[0])
					config.Dimensions[1], _ = strconv.Atoi(parts[1])
				}
			}
		case "-W", "--width":
			i++
			if i < len(os.Args) {
				config.Width, _ = strconv.Atoi(os.Args[i])
			}
		case "-H", "--height":
			i++
			if i < len(os.Args) {
				config.Height, _ = strconv.Atoi(os.Args[i])
			}
		case "-m", "--map":
			i++
			if i < len(os.Args) {
				config.Map = os.Args[i]
			}
		case "-b", "--braille":
			config.Braille = true
		case "--threshold":
			i++
			if i < len(os.Args) {
				config.Threshold, _ = strconv.Atoi(os.Args[i])
			}
		case "--dither":
			config.Dither = true
		case "-g", "--grayscale":
			config.Grayscale = true
		case "-c", "--complex":
			config.Complex = true
		case "-f", "--full":
			config.Full = true
		case "-n", "--negative":
			config.Negative = true
		case "-x", "--flipX":
			config.FlipX = true
		case "-y", "--flipY":
			config.FlipY = true
		case "-s", "--save-img":
			i++
			if i < len(os.Args) {
				config.SaveImg = os.Args[i]
			}
		case "--save-txt":
			i++
			if i < len(os.Args) {
				config.SaveTxt = os.Args[i]
			}
		case "--save-gif":
			i++
			if i < len(os.Args) {
				config.SaveGif = os.Args[i]
			}
		case "--only-save":
			config.OnlySave = true
		case "--formats":
			fmt.Println("Supported input formats:\n\nJPEG/JPG\nPNG\nWEBP\nBMP\nTIFF/TIF\nGIF\n")
			return
		case "-v", "--version":
			fmt.Println("v1.13.1")
			return
		case "-h", "--help":
			printHelp()
			return
		default:
			if !strings.HasPrefix(arg, "-") {
				inputs = append(inputs, arg)
			}
		}
	}
	if len(inputs) == 0 {
		fmt.Println("Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info\n")
		return
	}
	for _, input := range inputs {
		processInput(input, config)
	}
}

func printHelp() {
	fmt.Println("This tool converts images into ascii art and prints them on the terminal.\nFurther configuration can be managed with flags.\n\nUsage:\n  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\nFlags:\n  -C, --color             Display ascii art with original colors\n                          If 24-bit colors aren't supported, uses 8-bit\n                          (Inverts with --negative flag)\n                          (Overrides --grayscale and --font-color flags)\n                          \n      --color-bg          If some color flag is passed, use that color\n                          on character background instead of foreground\n                          (Inverts with --negative flag)\n                          (Only applicable for terminal display)\n                          \n  -d, --dimensions ints   Set width and height for ascii art in CHARACTER length\n                          e.g. -d 60,30 (defaults to terminal height)\n                          (Overrides --width and --height flags)\n                          \n  -W, --width int         Set width for ascii art in CHARACTER length\n                          Height is kept to aspect ratio\n                          e.g. -W 60\n                          \n  -H, --height int        Set height for ascii art in CHARACTER length\n                          Width is kept to aspect ratio\n                          e.g. -H 60\n                          \n  -m, --map string        Give custom ascii characters to map against\n                          Ordered from darkest to lightest\n                          e.g. -m \" .-+#@\" (Quotation marks excluded from map)\n                          (Overrides --complex flag)\n                          \n  -b, --braille           Use braille characters instead of ascii\n                          Terminal must support braille patterns properly\n                          (Overrides --complex and --map flags)\n                          \n      --threshold int     Threshold for braille art\n                          Value between 0-255 is accepted\n                          e.g. --threshold 170\n                          (Defaults to 128)\n                          \n      --dither            Apply dithering on image for braille\n                          art conversion\n                          (Only applicable with --braille flag)\n                          (Negates --threshold flag)\n                          \n  -g, --grayscale         Display grayscale ascii art\n                          (Inverts with --negative flag)\n                          (Overrides --font-color flag)\n                          \n  -c, --complex           Display ascii characters in a larger range\n                          May result in higher quality\n                          \n  -f, --full              Use largest dimensions for ascii art\n                          that fill the terminal width\n                          (Overrides --dimensions, --width and --height flags)\n                          \n  -n, --negative          Display ascii art in negative colors\n                          \n  -x, --flipX             Flip ascii art horizontally\n                          \n  -y, --flipY             Flip ascii art vertically\n                          \n  -s, --save-img string   Save ascii art as a .png file\n                          Format: <image-name>-ascii-art.png\n                          Image will be saved in passed path\n                          (pass . for current directory)\n                          \n      --save-txt string   Save ascii art as a .txt file\n                          Format: <image-name>-ascii-art.txt\n                          File will be saved in passed path\n                          (pass . for current directory)\n                          \n      --save-gif string   If input is a gif, save it as a .gif file\n                          Format: <gif-name>-ascii-art.gif\n                          Gif will be saved in passed path\n                          (pass . for current directory)\n                          \n      --save-bg ints      Set background color for --save-img\n                          and --save-gif flags\n                          Pass an RGBA value\n                          e.g. --save-bg 255,255,255,100\n                          (Defaults to 0,0,0,100)\n                          \n      --font string       Set font for --save-img and --save-gif flags\n                          Pass file path to font .ttf file\n                          e.g. --font ./RobotoMono-Regular.ttf\n                          (Defaults to Hack-Regular for ascii and\n                           DejaVuSans-Oblique for braille)\n                          \n      --font-color ints   Set font color for terminal as well as\n                          --save-img and --save-gif flags\n                          Pass an RGB value\n                          e.g. --font-color 0,0,0\n                          (Defaults to 255,255,255)\n                          \n      --only-save         Don't print ascii art on terminal\n                          if some saving flag is passed\n                          \n      --formats           Display supported input formats\n                          \n  -h, --help              Help for ascii-image-converter\n                          \n  -v, --version           Version for ascii-image-converter\n\nCopyright © 2021 Zoraiz Hassan <hzoraiz8@gmail.com>\nDistributed under the Apache License Version 2.0 (Apache-2.0)\nFor further details, visit https://github.com/TheZoraiz/ascii-image-converter")
}

func processInput(input string, config Config) {
	var img image.Image
	var err error
	if strings.HasPrefix(input, "http://") || strings.HasPrefix(input, "https://") {
		resp, err := http.Get(input)
		if err != nil {
			fmt.Printf("Error: %v\n", err)
			return
		}
		defer resp.Body.Close()
		img, _, err = image.Decode(resp.Body)
	} else {
		file, err := os.Open(input)
		if err != nil {
			fmt.Printf("Error: %v\n", err)
			return
		}
		defer file.Close()
		img, _, err = image.Decode(file)
	}
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	imgW := img.Bounds().Dx()
	imgH := img.Bounds().Dy()

	termW, termH := getTerminalSize()

	var targetW, targetH int
	if config.Dimensions[0] != 0 && config.Dimensions[1] != 0 {
		targetW = config.Dimensions[0]
		targetH = config.Dimensions[1]
	} else if config.Full {
		targetW = termW
		if config.Braille {
			targetH = int(float64(targetW*2) * float64(imgH) / float64(imgW) / 4)
		} else {
			targetH = int(float64(targetW) * float64(imgH) / float64(imgW) * 0.5)
		}
	} else if config.Width != 0 {
		targetW = config.Width
		if config.Braille {
			targetH = int(float64(targetW*2) * float64(imgH) / float64(imgW) / 4)
		} else {
			targetH = int(float64(targetW) * float64(imgH) / float64(imgW) * 0.5)
		}
	} else if config.Height != 0 {
		targetH = config.Height
		if config.Braille {
			targetW = int(float64(targetH*4) * float64(imgW) / float64(imgH) / 2)
		} else {
			targetW = int(float64(targetH) * float64(imgW) / float64(imgH) / 0.5)
		}
	} else {
		targetH = termH
		if config.Braille {
			targetW = int(float64(targetH*4) * float64(imgW) / float64(imgH) / 2)
		} else {
			targetW = int(float64(targetH) * float64(imgW) / float64(imgH) / 0.5)
		}
        if targetW > termW {
            targetW = termW
            if config.Braille {
                targetH = int(float64(targetW*2) * float64(imgH) / float64(imgW) / 4)
            } else {
                targetH = int(float64(targetW) * float64(imgH) / float64(imgW) * 0.5)
            }
        }
	}

	if targetW < 1 { targetW = 1 }
	if targetH < 1 { targetH = 1 }

	if config.Braille {
		renderBraille(img, targetW, targetH, config, input)
	} else {
		renderAscii(img, targetW, targetH, config, input)
	}
}

func getLuminance(r, g, b uint32) float64 {
	return 0.299*float64(r>>8) + 0.587*float64(g>>8) + 0.114*float64(b>>8)
}

func renderAscii(img image.Image, targetW, targetH int, config Config, inputName string) {
	charMap := defaultMap
	if config.Complex {
		charMap = complexMap
	}
	if config.Map != "" {
		charMap = config.Map
	}
	if config.Negative {
		charMap = reverseString(charMap)
	}

	resized := resizeBilinear(img, targetW, targetH)
    if config.FlipX { resized = flipX(resized) }
    if config.FlipY { resized = flipY(resized) }

	var result strings.Builder
	for y := 0; y < targetH; y++ {
		for x := 0; x < targetW; x++ {
			c := resized.At(x, y)
			r, g, b, _ := c.RGBA()
			lum := getLuminance(r, g, b)
			charIdx := int(math.Round(lum)) * len(charMap) / 256
			if charIdx >= len(charMap) { charIdx = len(charMap) - 1 }
			char := string(charMap[charIdx])

			if !config.OnlySave {
				if config.Color {
					fmt.Print(getColorCode(r, g, b, config.ColorBG, config.Negative) + char + "\x1b[0m")
				} else if config.Grayscale {
                    gLum := uint8(math.Round(lum))
                    if config.Negative { gLum = 255 - gLum }
                    fmt.Print(getGrayscaleCode(gLum, config.ColorBG) + char + "\x1b[0m")
                } else {
					fmt.Print(char)
				}
			}
			result.WriteString(char)
		}
		if !config.OnlySave {
			fmt.Println()
		}
		if y < targetH-1 {
			result.WriteString("\n")
		}
	}

	if config.SaveTxt != "" {
		saveTxt(result.String(), config.SaveTxt, inputName)
	}
}

func renderBraille(img image.Image, targetW, targetH int, config Config, inputName string) {
	dotW := targetW * 2
	dotH := targetH * 4
	resized := resizeBilinear(img, dotW, dotH)
    if config.FlipX { resized = flipX(resized) }
    if config.FlipY { resized = flipY(resized) }

	var result strings.Builder
	for y := 0; y < targetH; y++ {
		for x := 0; x < targetW; x++ {
			var dots [8]bool
			var rAvg, gAvg, bAvg uint32
			var count uint32
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					px := x*2 + dx
					py := y*4 + dy
					c := resized.At(px, py)
					r, g, b, _ := c.RGBA()
					lum := getLuminance(r, g, b)
					if lum >= float64(config.Threshold) {
						dots[getBrailleIndex(dx, dy)] = true
					}
					rAvg += r >> 8
					gAvg += g >> 8
					bAvg += b >> 8
					count++
				}
			}
			rAvg /= count
			gAvg /= count
			bAvg /= count
			char := string(getBrailleChar(dots))

			if !config.OnlySave {
				if config.Color {
					fmt.Print(getColorCode(rAvg<<8, gAvg<<8, bAvg<<8, config.ColorBG, config.Negative) + char + "\x1b[0m")
				} else {
					fmt.Print(char)
				}
			}
			result.WriteString(char)
		}
		if !config.OnlySave {
			fmt.Println()
		}
		if y < targetH-1 {
			result.WriteString("\n")
		}
	}
	if config.SaveTxt != "" {
		saveTxt(result.String(), config.SaveTxt, inputName)
	}
}

func getBrailleIndex(dx, dy int) int {
	// Dot 1: (0,0), Dot 2: (0,1), Dot 3: (0,2), Dot 4: (1,0), Dot 5: (1,1), Dot 6: (1,2), Dot 7: (0,3), Dot 8: (1,3)
	if dx == 0 {
		return dy // 0, 1, 2, 3
	}
    if dy == 3 { return 7 }
	return dy + 3 // 4, 5, 6
}

func getBrailleChar(dots [8]bool) rune {
	r := rune(0x2800)
	for i := 0; i < 8; i++ {
		if dots[i] {
			r |= (1 << i)
		}
	}
	return r
}

func getColorCode(r, g, b uint32, bg bool, negative bool) string {
    r8, g8, b8 := uint8(r>>8), uint8(g>>8), uint8(b>>8)
    if negative {
        r8 = 255 - r8
        g8 = 255 - g8
        b8 = 255 - b8
    }
	prefix := "38"
	if bg { prefix = "48" }

	if os.Getenv("COLORTERM") == "truecolor" || os.Getenv("COLORTERM") == "24bit" {
		return fmt.Sprintf("\x1b[%s;2;%d;%d;%dm", prefix, r8, g8, b8)
	}

    // Fallback to 8-bit color
    return fmt.Sprintf("\x1b[%s;5;%dm", prefix, rgbToAnsi256(r8, g8, b8))
}

func getGrayscaleCode(lum uint8, bg bool) string {
    prefix := "38"
    if bg { prefix = "48" }
    return fmt.Sprintf("\x1b[%s;5;%dm", prefix, grayscaleToAnsi256(lum))
}

func rgbToAnsi256(r, g, b uint8) int {
    if r == g && g == b {
        return grayscaleToAnsi256(r)
    }
    return 16 + (int(r)*5/255)*36 + (int(g)*5/255)*6 + (int(b)*5/255)
}

func grayscaleToAnsi256(lum uint8) int {
    if lum < 8 { return 16 } // Black
    if lum > 248 { return 231 } // White
    return 232 + int((float64(lum)-8)/240*24)
}

func reverseString(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

func resizeBilinear(img image.Image, w, h int) image.Image {
	newImg := image.NewRGBA(image.Rect(0, 0, w, h))
	srcW := img.Bounds().Dx()
	srcH := img.Bounds().Dy()
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			srcX := (float64(x) + 0.5) * float64(srcW) / float64(w) - 0.5
			srcY := (float64(y) + 0.5) * float64(srcH) / float64(h) - 0.5
			x1 := int(math.Floor(srcX))
			y1 := int(math.Floor(srcY))
			x2 := x1 + 1
			y2 := y1 + 1
			dx := srcX - float64(x1)
			dy := srcY - float64(y1)
			val := [4]float64{}
			for i := 0; i < 4; i++ {
				v11 := getSample(img, x1, y1, i)
				v21 := getSample(img, x2, y1, i)
				v12 := getSample(img, x1, y2, i)
				v22 := getSample(img, x2, y2, i)
				val[i] = lerp(lerp(v11, v21, dx), lerp(v12, v22, dx), dy)
			}
			newImg.Set(x, y, color.RGBA64{uint16(val[0]), uint16(val[1]), uint16(val[2]), uint16(val[3])})
		}
	}
	return newImg
}

func getSample(img image.Image, x, y, channel int) float64 {
	if x < 0 { x = 0 }
	if x >= img.Bounds().Dx() { x = img.Bounds().Dx() - 1 }
	if y < 0 { y = 0 }
	if y >= img.Bounds().Dy() { y = img.Bounds().Dy() - 1 }
	r, g, b, a := img.At(x + img.Bounds().Min.X, y + img.Bounds().Min.Y).RGBA()
	switch channel {
	case 0: return float64(r)
	case 1: return float64(g)
	case 2: return float64(b)
	case 3: return float64(a)
	}
	return 0
}

func lerp(v1, v2, t float64) float64 {
	return v1*(1-t) + v2*t
}

func flipX(img image.Image) image.Image {
    b := img.Bounds()
    newImg := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
    for y := 0; y < b.Dy(); y++ {
        for x := 0; x < b.Dx(); x++ {
            newImg.Set(b.Dx()-1-x, y, img.At(x+b.Min.X, y+b.Min.Y))
        }
    }
    return newImg
}

func flipY(img image.Image) image.Image {
    b := img.Bounds()
    newImg := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
    for y := 0; y < b.Dy(); y++ {
        for x := 0; x < b.Dx(); x++ {
            newImg.Set(x, b.Dy()-1-y, img.At(x+b.Min.X, y+b.Min.Y))
        }
    }
    return newImg
}

func saveTxt(content, path, inputName string) {
	base := filepath.Base(inputName)
	ext := filepath.Ext(base)
	name := base[:len(base)-len(ext)]
	filename := filepath.Join(path, name+"-ascii-art.txt")
	err := os.WriteFile(filename, []byte(content), 0644)
	if err == nil {
		fmt.Printf("Saved %s\n", filename)
	} else {
        fmt.Printf("Error saving txt: %v\n", err)
    }
}
