func decodeBMP(r io.Reader) (image.Image, error) {
	var header [14]byte
	if _, err := io.ReadFull(r, header[:]); err != nil {
		return nil, err
	}
	if header[0] != 'B' || header[1] != 'M' {
		return nil, fmt.Errorf("not a BMP")
	}
	var dibHeader [40]byte
	if _, err := io.ReadFull(r, dibHeader[:]); err != nil {
		return nil, err
	}
	width := int(int32(binary.LittleEndian.Uint32(dibHeader[4:8])))
	height := int(int32(binary.LittleEndian.Uint32(dibHeader[8:12])))
	bitCount := binary.LittleEndian.Uint16(dibHeader[14:16])
	if bitCount != 24 {
		return nil, fmt.Errorf("only 24-bit BMP supported")
	}
	absHeight := int(math.Abs(float64(height)))
	img := image.NewRGBA(image.Rect(0, 0, width, absHeight))
	rowSize := (width*3 + 3) &^ 3
	rowData := make([]byte, rowSize)
	for y := 0; y < absHeight; y++ {
		if _, err := io.ReadFull(r, rowData); err != nil {
			return nil, err
		}
		actualY := y
		if height > 0 {
			actualY = absHeight - 1 - y
		}
		for x := 0; x < width; x++ {
			b := rowData[x*3]
			g := rowData[x*3+1]
			r := rowData[x*3+2]
			img.Set(x, actualY, color.RGBA{r, g, b, 255})
		}
	}
	return img, nil
}

func init() {
	image.RegisterFormat("bmp", "BM", decodeBMP, func(r io.Reader) (image.Config, error) {
		var h [26]byte
		if _, err := io.ReadFull(r, h[:]); err != nil {
			return image.Config{}, err
		}
		return image.Config{
			ColorModel: color.RGBAModel,
			Width:      int(binary.LittleEndian.Uint32(h[18:22])),
			Height:     int(binary.LittleEndian.Uint32(h[22:26])),
		}, nil
	})
}

func getTerminalSize() (int, int) {
	width, height := 80, 24
	fd := int(os.Stdout.Fd())
	var dimensions [4]uint16
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&dimensions)), 0, 0, 0)
	if err == 0 {
		width = int(dimensions[1])
		height = int(dimensions[0])
	}
	return width, height
}

