func getBrailleIndex(dx, dy int) int {
	// Dot 1: (0,0), Dot 2: (0,1), Dot 3: (0,2), Dot 4: (1,0), Dot 5: (1,1), Dot 6: (1,2), Dot 7: (0,3), Dot 8: (1,3)
	if dx == 0 {
		return dy // 0, 1, 2, 3
	}
    if dy == 3 { return 7 }
	return dy + 3 // 4, 5, 6
}

func getBrailleChar(dots [8]bool) rune {
	r := rune(0x2800)
	for i := 0; i < 8; i++ {
		if dots[i] {
			r |= (1 << i)
		}
	}
	return r
}

func getColorCode(r, g, b uint32, bg bool, negative bool) string {
    r8, g8, b8 := uint8(r>>8), uint8(g>>8), uint8(b>>8)
    if negative {
        r8 = 255 - r8
        g8 = 255 - g8
        b8 = 255 - b8
    }
	prefix := "38"
	if bg { prefix = "48" }

	if os.Getenv("COLORTERM") == "truecolor" || os.Getenv("COLORTERM") == "24bit" {
		return fmt.Sprintf("\x1b[%s;2;%d;%d;%dm", prefix, r8, g8, b8)
	}

    // Fallback to 8-bit color
    return fmt.Sprintf("\x1b[%s;5;%dm", prefix, rgbToAnsi256(r8, g8, b8))
}

func getGrayscaleCode(lum uint8, bg bool) string {
    prefix := "38"
    if bg { prefix = "48" }
    return fmt.Sprintf("\x1b[%s;5;%dm", prefix, grayscaleToAnsi256(lum))
}

func rgbToAnsi256(r, g, b uint8) int {
    if r == g && g == b {
        return grayscaleToAnsi256(r)
    }
    return 16 + (int(r)*5/255)*36 + (int(g)*5/255)*6 + (int(b)*5/255)
}

func grayscaleToAnsi256(lum uint8) int {
    if lum < 8 { return 16 } // Black
    if lum > 248 { return 231 } // White
    return 232 + int((float64(lum)-8)/240*24)
}

func reverseString(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

func resizeBilinear(img image.Image, w, h int) image.Image {
	newImg := image.NewRGBA(image.Rect(0, 0, w, h))
	srcW := img.Bounds().Dx()
	srcH := img.Bounds().Dy()
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			srcX := (float64(x) + 0.5) * float64(srcW) / float64(w) - 0.5
			srcY := (float64(y) + 0.5) * float64(srcH) / float64(h) - 0.5
			x1 := int(math.Floor(srcX))
			y1 := int(math.Floor(srcY))
			x2 := x1 + 1
			y2 := y1 + 1
			dx := srcX - float64(x1)
			dy := srcY - float64(y1)
			val := [4]float64{}
			for i := 0; i < 4; i++ {
				v11 := getSample(img, x1, y1, i)
				v21 := getSample(img, x2, y1, i)
				v12 := getSample(img, x1, y2, i)
				v22 := getSample(img, x2, y2, i)
				val[i] = lerp(lerp(v11, v21, dx), lerp(v12, v22, dx), dy)
			}
			newImg.Set(x, y, color.RGBA64{uint16(val[0]), uint16(val[1]), uint16(val[2]), uint16(val[3])})
		}
	}
	return newImg
}

func getSample(img image.Image, x, y, channel int) float64 {
	if x < 0 { x = 0 }
	if x >= img.Bounds().Dx() { x = img.Bounds().Dx() - 1 }
	if y < 0 { y = 0 }
	if y >= img.Bounds().Dy() { y = img.Bounds().Dy() - 1 }
	r, g, b, a := img.At(x + img.Bounds().Min.X, y + img.Bounds().Min.Y).RGBA()
	switch channel {
	case 0: return float64(r)
	case 1: return float64(g)
	case 2: return float64(b)
	case 3: return float64(a)
	}
	return 0
}

func lerp(v1, v2, t float64) float64 {
	return v1*(1-t) + v2*t
}

func flipX(img image.Image) image.Image {
    b := img.Bounds()
    newImg := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
    for y := 0; y < b.Dy(); y++ {
        for x := 0; x < b.Dx(); x++ {
            newImg.Set(b.Dx()-1-x, y, img.At(x+b.Min.X, y+b.Min.Y))
        }
    }
    return newImg
}

func flipY(img image.Image) image.Image {
    b := img.Bounds()
    newImg := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
    for y := 0; y < b.Dy(); y++ {
        for x := 0; x < b.Dx(); x++ {
            newImg.Set(x, b.Dy()-1-y, img.At(x+b.Min.X, y+b.Min.Y))
        }
    }
    return newImg
}

func saveTxt(content, path, inputName string) {
	base := filepath.Base(inputName)
	ext := filepath.Ext(base)
	name := base[:len(base)-len(ext)]
	filename := filepath.Join(path, name+"-ascii-art.txt")
	err := os.WriteFile(filename, []byte(content), 0644)
	if err == nil {
		fmt.Printf("Saved %s\n", filename)
	} else {
        fmt.Printf("Error saving txt: %v\n", err)
    }
}
