func getLuminance(r, g, b uint32) float64 {
	return 0.299*float64(r>>8) + 0.587*float64(g>>8) + 0.114*float64(b>>8)
}

func renderAscii(img image.Image, targetW, targetH int, config Config, inputName string) {
	resized := resizeBilinear(img, targetW, targetH)
	if config.FlipX { resized = flipX(resized) }
	if config.FlipY { resized = flipY(resized) }

	var result strings.Builder
	for y := 0; y < targetH; y++ {
		for x := 0; x < targetW; x++ {
			c := resized.At(x, y)
			r, g, b, _ := c.RGBA()
			lum := getLuminance(r, g, b)

			var char string
			if config.Map != "" {
				charMap := config.Map
				if config.Negative { charMap = reverseString(charMap) }
				charIdx := int(math.Round(lum)) * len(charMap) / 256
				if charIdx >= len(charMap) { charIdx = len(charMap) - 1 }
				char = string(charMap[charIdx])
			} else if config.Complex {
				lookup := complexLookup
				if config.Negative { lookup = reverseLookup(lookup) }
				char = string(lookup[int(math.Round(lum))])
			} else {
				lookup := defaultLookup
				if config.Negative { lookup = reverseLookup(lookup) }
				char = string(lookup[int(math.Round(lum))])
			}

			if !config.OnlySave {
				if config.Color {
					fmt.Print(getColorCode(r, g, b, config.ColorBG, config.Negative) + char + "\x1b[0m")
				} else if config.Grayscale {
					gLum := uint8(math.Round(lum))
					if config.Negative { gLum = 255 - gLum }
					fmt.Print(getGrayscaleCode(gLum, config.ColorBG) + char + "\x1b[0m")
				} else {
					fmt.Print(char)
				}
			}
			result.WriteString(char)
		}
		if !config.OnlySave {
			fmt.Println()
		}
		if y < targetH-1 {
			result.WriteString("\n")
		}
	}
	if config.SaveTxt != "" {
		saveTxt(result.String(), config.SaveTxt, inputName)
	}
}

func reverseLookup(s string) string {
    runes := []rune(s)
    res := make([]rune, 256)
    for i := 0; i < 256; i++ {
        res[i] = runes[255-i]
    }
    return string(res)
}

func renderBraille(img image.Image, targetW, targetH int, config Config, inputName string) {
	dotW := targetW * 2
	dotH := targetH * 4
	resized := resizeBilinear(img, dotW, dotH)
	if config.FlipX { resized = flipX(resized) }
	if config.FlipY { resized = flipY(resized) }

	var result strings.Builder
	for y := 0; y < targetH; y++ {
		for x := 0; x < targetW; x++ {
			var dots [8]bool
			var rAvg, gAvg, bAvg uint32
			var count uint32
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					px := x*2 + dx
					py := y*4 + dy
					c := resized.At(px, py)
					r, g, b, _ := c.RGBA()
					lum := getLuminance(r, g, b)
					if lum >= float64(config.Threshold) {
						dots[getBrailleIndex(dx, dy)] = true
					}
					rAvg += r >> 8
					gAvg += g >> 8
					bAvg += b >> 8
					count++
				}
			}
			rAvg /= count
			gAvg /= count
			bAvg /= count
			char := string(getBrailleChar(dots))
			if !config.OnlySave {
				if config.Color {
					fmt.Print(getColorCode(rAvg<<8, gAvg<<8, bAvg<<8, config.ColorBG, config.Negative) + char + "\x1b[0m")
				} else {
					fmt.Print(char)
				}
			}
			result.WriteString(char)
		}
		if !config.OnlySave {
			fmt.Println()
		}
		if y < targetH-1 {
			result.WriteString("\n")
		}
	}
	if config.SaveTxt != "" {
		saveTxt(result.String(), config.SaveTxt, inputName)
	}
}

func getBrailleIndex(dx, dy int) int {
	if dx == 0 {
		return dy
	}
	if dy == 3 { return 7 }
	return dy + 3
}

func getBrailleChar(dots [8]bool) rune {
	r := rune(0x2800)
	for i := 0; i < 8; i++ {
		if dots[i] {
			r |= (1 << i)
		}
	}
	return r
}

func getColorCode(r, g, b uint32, bg bool, negative bool) string {
	r8, g8, b8 := uint8(r>>8), uint8(g>>8), uint8(b>>8)
	if negative {
		r8 = 255 - r8
		g8 = 255 - g8
		b8 = 255 - b8
	}
	prefix := "38"
	if bg { prefix = "48" }
	if os.Getenv("COLORTERM") == "truecolor" || os.Getenv("COLORTERM") == "24bit" {
		return fmt.Sprintf("\x1b[%s;2;%d;%d;%dm", prefix, r8, g8, b8)
	}
	return fmt.Sprintf("\x1b[%s;5;%dm", prefix, rgbToAnsi256(r8, g8, b8))
}

func getGrayscaleCode(lum uint8, bg bool) string {
	prefix := "38"
	if bg { prefix = "48" }
	return fmt.Sprintf("\x1b[%s;5;%dm", prefix, grayscaleToAnsi256(lum))
}

func rgbToAnsi256(r, g, b uint8) int {
    if r == g && g == b { return grayscaleToAnsi256(r) }
    return 16 + (int(r)*5/255)*36 + (int(g)*5/255)*6 + (int(b)*5/255)
}

func grayscaleToAnsi256(lum uint8) int {
	if lum < 8 { return 16 }
	if lum > 248 { return 231 }
	return 232 + int((float64(lum)-8)/240*24)
}

func reverseString(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

func resizeBilinear(img image.Image, w, h int) image.Image {
	newImg := image.NewRGBA(image.Rect(0, 0, w, h))
	srcW := img.Bounds().Dx()
	srcH := img.Bounds().Dy()
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			srcX := (float64(x) + 0.5) * float64(srcW) / float64(w) - 0.5
			srcY := (float64(y) + 0.5) * float64(srcH) / float64(h) - 0.5
			x1 := int(math.Floor(srcX))
			y1 := int(math.Floor(srcY))
			x2 := x1 + 1
			y2 := y1 + 1
			dx := srcX - float64(x1)
			dy := srcY - float64(y1)
			val := [4]float64{}
			for i := 0; i < 4; i++ {
				v11 := getSample(img, x1, y1, i)
				v21 := getSample(img, x2, y1, i)
				v12 := getSample(img, x1, y2, i)
				v22 := getSample(img, x2, y2, i)
				val[i] = lerp(lerp(v11, v21, dx), lerp(v12, v22, dx), dy)
			}
			newImg.Set(x, y, color.RGBA64{uint16(val[0]), uint16(val[1]), uint16(val[2]), uint16(val[3])})
		}
	}
	return newImg
}

func getSample(img image.Image, x, y, channel int) float64 {
	if x < 0 { x = 0 }
	if x >= img.Bounds().Dx() { x = img.Bounds().Dx() - 1 }
	if y < 0 { y = 0 }
	if y >= img.Bounds().Dy() { y = img.Bounds().Dy() - 1 }
	r, g, b, a := img.At(x+img.Bounds().Min.X, y+img.Bounds().Min.Y).RGBA()
	switch channel {
	case 0: return float64(r)
	case 1: return float64(g)
	case 2: return float64(b)
	case 3: return float64(a)
	}
	return 0
}

func lerp(v1, v2, t float64) float64 {
	return v1*(1-t) + v2*t
}

func flipX(img image.Image) image.Image {
	b := img.Bounds()
	newImg := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			newImg.Set(b.Dx()-1-x, y, img.At(x+b.Min.X, y+b.Min.Y))
		}
	}
	return newImg
}

func flipY(img image.Image) image.Image {
	b := img.Bounds()
	newImg := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			newImg.Set(x, b.Dy()-1-y, img.At(x+b.Min.X, y+b.Min.Y))
		}
	}
	return newImg
}

func saveTxt(content, path, inputName string) {
	base := filepath.Base(inputName)
	ext := filepath.Ext(base)
	name := base[:len(base)-len(ext)]
	filename := filepath.Join(path, name+"-ascii-art.txt")
	err := os.WriteFile(filename, []byte(content), 0644)
	if err == nil {
		fmt.Printf("Saved %s\n", filename)
	}
}
